<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/app/bootstrap.php';
use WexaShelf\{Config,Database,Repository,BackupTransfer};
try{$o=getopt('',['file:','sha256:','apply','confirm-catalog-replacement']);if(!is_string($o['file']??null)||!is_string($o['sha256']??null))throw new RuntimeException('Usage: WEXA_STORAGE_PATH=/private/storage php backup-restore.php --file=/private/backup.json --sha256=HASH [--apply --confirm-catalog-replacement]');$apply=array_key_exists('apply',$o);if($apply&&!array_key_exists('confirm-catalog-replacement',$o))throw new RuntimeException('Explicit --confirm-catalog-replacement required.');$config=Config::load();if(!$config)throw new RuntimeException('Installed private configuration required.');$db=Database::connect($config);$repo=new Repository($db,$config);$backup=BackupTransfer::decodeFile($o['file'],$o['sha256']);$preview=$repo->restoreBackup($backup,true);if(!$apply){fwrite(STDOUT,json_encode(['dryRun'=>true,'preview'=>$preview],JSON_THROW_ON_ERROR)."\n");exit;}$result=$repo->transaction(fn()=>$repo->restoreBackup($backup));fwrite(STDOUT,json_encode(['applied'=>true,'result'=>$result],JSON_THROW_ON_ERROR)."\n");}catch(Throwable $e){fwrite(STDERR,$e instanceof RuntimeException?$e->getMessage()."\n":"Restore failed; catalog transaction was not committed. Inspect private host logs.\n");exit(1);}
